function payoutRows(){return workspace.payouts.filter(p=>(!fromDate||p.dueDate>=fromDate)&&(!toDate||p.dueDate<=toDate))}
statement=function(){let rows=payoutRows(),pending=rows.filter(p=>p.status!=='Cleared'),cleared=rows.filter(p=>p.status==='Cleared'),sum=a=>a.reduce((s,p)=>s+amount(p.points),0),overdue=pending.filter(p=>p.dueDate<dateISO());return heading('MY STATEMENT','My payout statement','Track recorded points and their clearing dates.',pageActions('statement'))+connectionNote()+`<div class="toolbar"><label class="field">From<input type="date" value="${fromDate}" onchange="fromDate=this.value;render()"></label><label class="field">To<input type="date" value="${toDate}" onchange="toDate=this.value;render()"></label></div><div class="metrics">${metric('Total due',sum(pending)+' pts','clock',pending.length+' bookings')}${metric('Next cycle due',sum(pending.filter(p=>p.dueDate>=dateISO()))+' pts','calendar','From recorded dates')}${metric('Overdue',sum(overdue)+' pts','clock',overdue.length+' records')}${metric('Total cleared',sum(cleared)+' pts','check','Recorded cleared payouts')}</div><section class="card"><div class="cardhead"><h2>Upcoming payouts</h2></div>${payoutTable(pending)}</section><section class="card" style="margin-top:22px"><div class="cardhead"><h2>Recently cleared</h2></div>${payoutTable(cleared)}</section><p class="subtle">No payout provider is connected. No payment has been scheduled or executed by this workspace. Import your own verified statement in Workspace settings.</p>`}
function payoutTable(rows){return rows.length?`<div class="tablewrap"><table><thead><tr><th>Customer / policy</th><th>Points</th><th>Due</th><th>Status</th><th>Cleared</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.name||p.policy)}</td><td>${amount(p.points)} pts</td><td>${esc(p.dueDate)}</td><td>${esc(p.status)}</td><td>${esc(p.clearedDate||'—')}</td></tr>`).join('')}</tbody></table></div>`:emptyCard('All caught up','No payout records in this view.')}
overview=function(){let s=bookingStats(db.bookings),pending=workspace.payouts.filter(p=>p.status!=='Cleared').reduce((n,p)=>n+amount(p.points),0),cleared=workspace.payouts.filter(p=>p.status==='Cleared').reduce((n,p)=>n+amount(p.points),0),newLeads=db.leads.filter(l=>normalStage(l.status)==='New');return heading('PARTNER COMMAND CENTER','My dashboard','Your policies, leads, points and renewals in one place.',btn('Add My Booking','mapBooking()','plus',true))+connectionNote()+`<section class="welcome-banner"><div class="welcome-copy"><span class="welcome-kicker">${I('shield')} YOUR INSURANCE BUSINESS, SIMPLIFIED.</span><h2>Welcome back,<br><em>${esc(workspace.profile.name||'Partner')}.</em></h2><p>Start a new lead, follow your policies, and stay on top of renewals.</p><div class="welcome-actions">${btn('Create a lead',"go('sell')",'plus',true)}${btn('View bookings',"go('bookings')",'shield')}</div></div><div class="welcome-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="art-shield">${I('shield')}</div></div></section><div class="metrics">${metric('Business volume',rupee(s.premium),'trend',db.bookings.length+' recorded policies')}${metric('Lead points',s.gross+' pts','target','Recorded gross points')}${metric('Points received',cleared+' pts','wallet','From imported payout records')}${metric('Points pending',pending+' pts','clock','From imported payout records')}</div><div class="sectiontitle"><h2>Sell insurance — new lead</h2>${btn('View all',"go('sell')",'grid')}</div><div class="product-grid">${products.map(([p,i])=>`<button class="product" onclick="${p==='All products'?"go('sell')":`startLead('${p}')`}"><span class="product-symbol">${I(i)}</span><strong>${p}</strong></button>`).join('')}</div><div class="bottomgrid"><section class="card pad"><h2>My leads</h2>${newLeads.length?newLeads.slice(0,4).map(l=>`<div class="activity"><div><strong>${esc(l.name)}</strong><small>${esc(l.product)} · ${esc(l.phone||'')}</small></div>${btn('View',`leadDetail('${l.id}')`,'file')}</div>`).join(''):emptyCard('No new leads','Create a lead from the product shortcuts above.')}${btn('View all leads',"go('leads')")}</section><section class="card pad"><h2>Refer a friend</h2><p class="paneltext">Grow your network and track your recorded partner business.</p>${btn('My network',"go('network')",'users',true)}</section></div><div class="performance-grid" style="margin-top:22px"><section class="card pad"><h2>Business trend</h2>${actualTrend()}</section><section class="card pad"><h2>By product</h2>${[...new Set(db.bookings.map(b=>b.product))].map(p=>`<div class="settingsrow"><span>${esc(p)}</span><strong>${rupee(db.bookings.filter(b=>b.product===p).reduce((n,b)=>n+amount(b.premium),0))}</strong></div>`).join('')||emptyCard('No data yet','Product mix appears after your first booking.')}</section></div><div class="split">${['This month','Next month'].map(w=>`<section class="card pad"><h2>${w} renewals</h2>${db.bookings.filter(b=>!b.renewed&&inDateWindow(b.renewal,w)).map(b=>`<div class="activity"><div><strong>${esc(b.name)}</strong><small>${esc(b.product)} · ${esc(b.renewal)}</small></div>${btn('View',`viewBooking('${b.id}')`)}</div>`).join('')||emptyCard('No renewals due','All clear for this period.')}</section>`).join('')}</div>`}
function actualTrend(){let now=new Date(),months=Array.from({length:6},(_,i)=>new Date(now.getFullYear(),now.getMonth()-5+i,1)),values=months.map(m=>db.bookings.filter(b=>b.date?.slice(0,7)===`${m.getFullYear()}-${String(m.getMonth()+1).padStart(2,'0')}`).reduce((s,b)=>s+amount(b.premium),0)),max=Math.max(1,...values);return `<div class="bar-chart" role="img" aria-label="Recorded premium in the last six months">${months.map((m,i)=>`<div><span>${rupee(values[i])}</span><i style="height:${Math.max(2,values[i]/max*140)}px"></i><small>${m.toLocaleString('en',{month:'short'})}</small></div>`).join('')}</div>`}
sell=function(){return heading('REFER & EARN','Create a new lead','Choose a product to open its dedicated requirements form.',btn('Referral link','copyLink()','copy'))+`<div class="catalogue">${[['General insurance',['Health','Motor','Travel','Group Health','Group PA','Home']],['Life & investments',['Term','Investment','Mutual Fund']],['Commercial & other',['Fire & Burglary','Jewellery Block','Marine','Workmen Comp']]].map(([title,list])=>`<section><div class="sectiontitle"><h2>${title}</h2></div><div class="product-grid">${list.map(p=>`<button class="product" ${['Marine','Workmen Comp'].includes(p)?'disabled':''} onclick="startLead('${p}')"><span class="product-symbol">${I(products.find(x=>x[0]===p)?.[1]||'briefcase')}</span><strong>${p}</strong><small>${p==='Jewellery Block'?'Request for quote':['Marine','Workmen Comp'].includes(p)?'Unavailable in reference':'Create lead'}</small></button>`).join('')}</div></section>`).join('')}</div>${wizard?`<section class="card pad"><h2>Saved draft: ${esc(wizard.product)}</h2>${btn('Resume draft',"go('leadform')",'file',true)}</section>`:''}`}
network=function(){let totalPoints=db.network.reduce((s,n)=>s+amount(n.points),0);return heading('MY NETWORK','Grow your sales force','Invite partners using your configured referral link.',btn('Invite via WhatsApp','invite()','users',true))+`<section class="hero"><div class="eyebrow">PARTNER NETWORK</div><h2>Grow your network.<br>Build lasting relationships.</h2><p>Network figures below are based on records imported into this workspace. Joining and referral attribution require a connected account service.</p>${btn('Set referral link',"settings()",'copy')}</section><div class="metrics">${metric('Active team',db.network.length,'users','Recorded partners')}${metric('Total points',totalPoints+' pts','wallet','Recorded')}${metric('Received',db.network.reduce((s,n)=>s+amount(n.received),0)+' pts','check','Recorded')}${metric('Due now',db.network.reduce((s,n)=>s+amount(n.due),0)+' pts','clock','Recorded')}</div><section class="card"><div class="cardhead"><h2>My ambassadors</h2></div>${db.network.length?`<div class="tablewrap"><table><thead><tr><th>Partner</th><th>City</th><th>Policies</th><th>Points</th></tr></thead><tbody>${db.network.map(n=>`<tr><td>${esc(n.name)}</td><td>${esc(n.city||'')}</td><td>${amount(n.policies)}</td><td>${amount(n.points)}</td></tr>`).join('')}</tbody></table></div>`:emptyCard('No agents in your network yet','Configure your own referral URL to start inviting partners.')}</section>`}
copyLink=function(){if(!workspace.profile.referralLink)return modal('Referral link not configured','<p>Add your own working referral or onboarding URL in Workspace settings. A dashboard navigation URL does not track referrals.</p>'+btn('Workspace settings','settings()','contact',true));copyText(workspace.profile.referralLink)};
invite=function(){if(!workspace.profile.referralLink)return copyLink();draftMessage(`Join my insurance partner network: ${workspace.profile.referralLink}`)};
function earnings(premium,points){return Math.round(amount(premium)*amount(points)/100*100)/100}
function rateRows(){return workspace.rates.filter(r=>(category==='All'||r.product===category)&&[r.insurer,r.plan,r.location,r.conditions].join(' ').toLowerCase().includes(query.toLowerCase()))}
ratePage=function(){return heading('MY RATE CARD','Payout command center','Compare your verified rate cards and calculate earnings.',btn('Import rates','importDataDialog("rates")','download')+btn('Add rate','rateEditor()','plus',true))+`<div class="notice">Your rate catalogue starts empty. Add or import rates you are authorised to use. No live insurer rate feed is connected.</div>${pillTabs(['All','Health','Investment','ULIP','Motor','SME','Travel','Term'],category,'setRateCategory')}<div class="toolbar">${inlineSearch('Search insurer, product, segment or notes…')}${btn(compactRates?'Comfortable':'Compact','compactRates=!compactRates;render()','grid')}${selectedRates.length?btn('Compare '+selectedRates.length,'compareRates()','shield',true):''}</div><div id="results">${rateResults()}</div>`}
function setRateCategory(c){category=c;render()}
rateResults=function(){let rows=rateRows();return rows.length?`<div class="ratecards ${compactRates?'compact':''}">${[...new Set(rows.map(r=>r.insurer))].map(insurer=>{let plans=rows.filter(r=>r.insurer===insurer);return `<details class="card" open><summary class="ratehead"><div><h3>${esc(insurer)}</h3><p>${plans.length} plans · top payout ${Math.max(...plans.map(p=>amount(p.fresh)))} pts</p></div></summary><div class="tablewrap"><table><thead><tr><th>Compare</th><th>Plan name</th><th>Location</th><th>Conditions</th><th>NB fresh</th><th>Port-in</th><th>Renewal</th><th>Valid from</th><th></th></tr></thead><tbody>${plans.map(r=>`<tr><td><input type="checkbox" aria-label="Compare ${esc(r.plan)}" ${selectedRates.includes(r.id)?'checked':''} onchange="selectRate('${r.id}',this.checked)"></td><td>${esc(r.plan)}</td><td>${esc(r.location||'')}</td><td>${esc(r.conditions||'')}</td><td>${amount(r.fresh).toFixed(2)} pts</td><td>${amount(r.port).toFixed(2)} pts</td><td>${amount(r.renewal).toFixed(2)} pts</td><td>${esc(r.validFrom||'')}</td><td>${btn('Calculate',`rateCalculator('${r.id}')`,'wallet')}${btn('Edit',`rateEditor('${r.id}')`,'file')}</td></tr>`).join('')}</tbody></table></div></details>`}).join('')}</div>`:'<section class="card">'+emptyCard('No rate cards loaded','Import your approved rate cards or add a plan manually.',btn('Add rate','rateEditor()','plus',true))+'</section>'}
function rateEditor(id=''){let r=workspace.rates.find(r=>r.id===id)||{};modal('Rate card plan',`<form onsubmit="event.preventDefault();saveRate(this,'${id}')"><div class="formgrid">${fieldHTML(F('insurer','Insurer','text',true),r.insurer)}${fieldHTML(F('plan','Plan name','text',true),r.plan)}${fieldHTML(F('product','Product','select',true,['Health','Investment','ULIP','Motor','SME','Travel','Term']),r.product||'Health')}${fieldHTML(F('location','Location scope'),r.location)}${fieldHTML(F('fresh','NB fresh points (%)','number',true),r.fresh)}${fieldHTML(F('port','Port-in points (%)','number',true),r.port)}${fieldHTML(F('renewal','Renewal points (%)','number',true),r.renewal)}${fieldHTML(F('validFrom','Valid from','date'),r.validFrom)}${fieldHTML(F('conditions','Special conditions','textarea'),r.conditions)}</div><div class="modalfoot"><button class="primary">Save rate</button></div></form>`)}
function saveRate(form,id){let d=Object.fromEntries(new FormData(form));for(let k of ['fresh','port','renewal'])if(amount(d[k])>100)return toast('Payout percentage must be between 0 and 100');if(id)Object.assign(workspace.rates.find(r=>r.id===id),d);else workspace.rates.push({...d,id:uid('RATE')});saveWorkspace();closeModal();render();toast('Rate saved')}
function selectRate(id,selected){if(selected&&selectedRates.length>=4){toast('Compare up to 4 plans');render();return}selectedRates=selected?[...new Set([...selectedRates,id])]:selectedRates.filter(x=>x!==id);render()}
function compareRates(){let rows=workspace.rates.filter(r=>selectedRates.includes(r.id));modal('Rate comparison',`<div class="tablewrap"><table><thead><tr><th>Feature</th>${rows.map(r=>`<th>${esc(r.insurer)}<br>${esc(r.plan)}</th>`).join('')}</tr></thead><tbody>${['product','location','conditions','fresh','port','renewal','validFrom'].map(k=>`<tr><th>${k}</th>${rows.map(r=>`<td>${esc(r[k]||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`)}
function rateCalculator(id){let r=workspace.rates.find(r=>r.id===id);modal('Calculate earnings',`<h3>${esc(r.insurer)} · ${esc(r.plan)}</h3><form oninput="document.querySelector('#earningsResult').textContent=rupee(earnings(this.premium.value,this.rate.value))"><div class="formgrid">${fieldHTML(F('premium','Commissionable premium (₹)','number',true),10000)}<label class="field">Business type<select name="rate"><option value="${amount(r.fresh)}">NB fresh (${amount(r.fresh)} pts)</option><option value="${amount(r.port)}">Port-in (${amount(r.port)} pts)</option><option value="${amount(r.renewal)}">Renewal (${amount(r.renewal)} pts)</option></select></label></div></form><div class="bigvalue" id="earningsResult">${rupee(earnings(10000,r.fresh))}</div><p>This calculation uses your entered rate and premium. It does not confirm a payable commission.</p>`)}
function refreshParityResults(){let el=document.querySelector('#results');if(['prospects','help'].includes(current)){let input=document.activeElement,pos=input?.selectionStart;render();let next=document.querySelector('.searchbox input');next?.focus();if(pos!=null)next?.setSelectionRange(pos,pos);return}if(!el)return;const builders={bookings:bookingResults,renewals:renewalResults,leads:leadResults,contacts:contactResults,rates:rateResults,marketing:marketingResults};if(builders[current])el.innerHTML=builders[current]();if(current==='marketing')loadAssetPreviews()}
function exportRows(kind){let rows=kind==='bookings'?parityBookings():kind==='renewals'?renewalRows():kind==='leads'?filteredLeads():kind==='contacts'?contactRows():kind==='statement'?payoutRows():workspace.rates;let flattened=rows.map(r=>Object.fromEntries(Object.entries(r).filter(([,v])=>typeof v!=='object')));let data=csv(flattened);if(data){fileDownload('sigma0nine-'+kind+'.csv',data);toast('Export downloaded')}}
download=exportRows;
function printDocument(title,html){let old=document.querySelector('#print-root');old?.remove();let root=document.createElement('div');root.id='print-root';root.innerHTML=`<header class="print-header"><img src="sigma0nine-logo.png" alt="Sigma0Nine"><span>${esc(dateISO())}</span></header><h1>${esc(title)}</h1>${html}`;document.body.appendChild(root);window.print()}
function printRecords(kind){let rows=kind==='bookings'?parityBookings():kind==='renewals'?renewalRows():kind==='leads'?filteredLeads():payoutRows();let fields=kind==='statement'?['name','policy','points','dueDate','status']:['name','phone','product','premium','status',kind==='renewals'?'renewal':'date'];printDocument(kind+' report',`<table><thead><tr>${fields.map(k=>`<th>${k}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${fields.map(k=>`<td>${esc(r[k]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table>`)}
function importDataDialog(kind){modal('Import '+kind,`<p>Choose a JSON array or a CSV with headers. Import adds records to your browser workspace.</p><code>${kind==='rates'?'insurer,plan,product,fresh,port,renewal,location,conditions,validFrom':kind==='payouts'?'name,policy,points,dueDate,status,clearedDate':'name,city,policies,points,received,due'}</code><p><input type="file" accept=".json,.csv" aria-label="Import ${kind}" onchange="importRecords('${kind}',this.files[0])"></p><div id="importPreview"></div>`)}
function parseCSV(input){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<input.length;i++){let c=input[i];if(c==='"'){if(quoted&&input[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&input[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('Unclosed quoted CSV field');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);let headers=(rows.shift()||[]).map(h=>h.replace(/^\uFEFF/,'').trim());return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??''])))}
let pendingImport;
async function importRecords(kind,file){try{if(!file||file.size>5*1024*1024)throw Error('Choose a file under 5 MB');let text=await file.text(),rows=file.name.endsWith('.json')?JSON.parse(text):parseCSV(text);if(!Array.isArray(rows)||!rows.length)throw Error('No records found');for(let row of rows){if(!row||typeof row!=='object')throw Error('Invalid record');if(kind==='rates'&&(!row.insurer||!row.plan||!row.product||!['fresh','port','renewal'].every(k=>row[k]!==''&&row[k]!=null&&Number.isFinite(Number(row[k]))&&+row[k]>=0&&+row[k]<=100)))throw Error('Rates require insurer, plan, product and valid fresh/port/renewal percentages');if(kind==='payouts'&&(!/^\d{4}-\d{2}-\d{2}$/.test(row.dueDate)||!Number.isFinite(Number(row.points))||+row.points<0||!['Pending','Cleared'].includes(row.status)))throw Error('Payouts require dueDate, nonnegative points and Pending/Cleared status');if(kind==='network'&&!row.name)throw Error('Partner name is required')}pendingImport={kind,rows};document.querySelector('#importPreview').innerHTML=`<p>${rows.length} records validated. Review your file before continuing.</p>${btn('Add records','confirmImport()','check',true)}`}catch(e){toast(e.message)}}
function confirmImport(){if(!pendingImport)return;let {kind,rows}=pendingImport;let dest=kind==='network'?db.network:workspace[kind];if(!Array.isArray(dest))return toast('Unsupported data type');dest.push(...rows.map(r=>({...r,id:uid(kind.toUpperCase())})));save();saveWorkspace();pendingImport=null;closeModal();render();toast('Records imported')}
